card.content:
{% set bad = ['unknown', 'unavailable', 'none', 'select_entity_first', ''] %}
{% set core = [
  ('Grid sensor', states('text.hpvc_grid_power_sensor')),
  ('Market/export price', states('text.hpvc_market_price_sensor')),
  ('All-in price', states('text.hpvc_all_in_price_sensor')),
  ('Solar power', states('text.hpvc_pv_power_sensor'))
] %}
{% set ns = namespace(done=0, total=4) %}
<ha-alert title="Welcome to Home PV Control" alert-type="warning">
Open the <b>Settings</b> tab using the <b>⚙️ Settings</b> button in the navigation bar and complete the required configuration. Settings save native user intent. Physical control remains disabled in this build.
</ha-alert>
<p><b>Setup progress:</b></p>
{% for label, ent in core %}
  {% set normalized = ent | trim | lower %}
  {% set configured = normalized not in bad and (normalized | regex_match('^[a-z0-9_]+[.][a-z0-9_]+$')) %}
  {% set valid = configured and states(normalized) not in bad and is_number(states(normalized)) %}
  {% if valid %}{% set ns.done = ns.done + 1 %}✅{% else %}❌{% endif %} **{{ label }}**
{% endfor %}
{% set count = states('number.hpvc_inverter_count') | int(0) %}
{% set inv = namespace(valid=count > 0, entities=[]) %}
{% for i in range(1, count + 1) %}
  {% set method = states('select.hpvc_pv' ~ i ~ '_control_method') | trim %}
  {% set unit = states('select.hpvc_pv' ~ i ~ '_limit_unit') | trim %}
  {% set full = states('number.hpvc_pv' ~ i ~ '_full_limit') | float(0) %}
  {% set low = states('number.hpvc_pv' ~ i ~ '_low_limit') | float(-1) %}
  {% set base_valid = method in ['Number entity', 'Action/service'] and unit in ['Watts', 'Percent'] and full >
0 and low >= 0 and low < full %}
  {% if method == 'Number entity' %}
    {% set ent = states('text.hpvc_pv' ~ i ~ '_limit_number') | trim | lower %}
    {% set configured = base_valid and ent not in bad and (ent | regex_match('^number[.][a-z0-9_]+$')) and ent not
in inv.entities %}
    {% set live = configured and states(ent) not in bad and is_number(states(ent)) %}
    {% if not live %}{% set inv.valid = false %}{% else %}{% set inv.entities = inv.entities + [ent] %}{% endif
%}
  {% elif method == 'Action/service' %}
    {% set action = states('text.hpvc_pv' ~ i ~ '_action') | trim | lower %}
    {% set value_field = states('text.hpvc_pv' ~ i ~ '_value_field') | trim %}
    {% set readback = states('text.hpvc_pv' ~ i ~ '_readback_entity') | trim | lower %}
    {% set configured = base_valid and (action | regex_match('^[a-z0-9_]+[.][a-z0-9_]+$')) and value_field != ''
and (readback in bad or (readback | regex_match('^[a-z0-9_]+[.][a-z0-9_]+$'))) %}
    {% set live = configured and (readback in bad or (states(readback) not in bad and is_number(states(readback))))
%}
    {% if not live %}{% set inv.valid = false %}{% endif %}
  {% else %}
    {% set inv.valid = false %}
  {% endif %}
{% endfor %}
{% set ns.total = ns.total + 1 %}
{% if inv.valid %}{% set ns.done = ns.done + 1 %}✅{% else %}❌{% endif %} **Inverter setup**

{% set ns.total = ns.total + 1 %}
{% set setup_ready = (state_attr('sensor.hpvc_status', 'ui_input_boolean_hpvc_defaults_applied') == 'on') and (state_attr('sensor.hpvc_status', 'ui_binary_sensor_hpvc_configuration_valid') == 'on') %}
{% if setup_ready %}{% set ns.done = ns.done + 1 %}✅{% else %}❌{% endif %} **Control settings**
<p><b>{{ ns.done }}/{{ ns.total }} complete</b></p>

