EVAL:function({ series, dataPointIndex }) {

  const colors = [
    '#3B82F6',
    '#22C55E',
    '#F59E0B'
  ];

  const names = [
    'Grid import',
    'Grid export',
    'Solar'
  ];

  let rows = '';

  // Only the first three visible graph series belong in the tooltip.
  for (let i = 0; i < 3; i++) {
    const value =
      series[i] && dataPointIndex < series[i].length
        ? series[i][dataPointIndex]
        : null;

    const display =
      value === null ||
      value === undefined ||
      !Number.isFinite(value)
        ? '—'
        : Math.round(value).toLocaleString() + ' W';

    rows +=
      '<div style="display:flex;align-items:center;gap:6px;margin:2px 0;">' +
        '<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:' +
          colors[i] +
          ';flex-shrink:0;"></span>' +
        '<span style="color:var(--secondary-text-color);min-width:88px;font-weight:700;">' +
          names[i] +
          '</span>' +
        '<span style="font-weight:700;margin-left:auto;">' +
          display +
        '</span>' +
      '</div>';
  }

  return (
    '<div style="padding:8px 10px;font-size:10px;width:max-content;max-width:240px;box-sizing:border-box;background:color-mix(in srgb,var(--ha-card-background,var(--card-background-color)) 35%,transparent);backdrop-filter:blur(1px);-webkit-backdrop-filter:blur(1px);border-radius:6px;border:1px solid var(--divider-color);color:var(--primary-text-color);font-family:inherit;box-shadow:none;font-weight:600;">' +
      rows +
    '</div>'
  );
}

tooltip.formatter:
EVAL:function(value) {
  const date = new Date(value);

  const months = [
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
  ];

  const pad = number =>
    String(number).padStart(2, '0');

  return (
    pad(date.getDate()) +
    ' ' +
    months[date.getMonth()] +
    ' · ' +
    pad(date.getHours()) +
    ':' +
    pad(date.getMinutes())
  );
}

