EVAL:function({ series, seriesIndex, dataPointIndex, w }) {

  const priceSeriesIndex =
    w &&
    w.config &&
    w.config.series
      ? w.config.series.findIndex(s => s.name === 'Price')
      : -1;

  const index =
    priceSeriesIndex >= 0
      ? priceSeriesIndex
      : seriesIndex;

  const value =
    series[index] &&
    dataPointIndex >= 0 &&
    dataPointIndex < series[index].length
      ? Number(series[index][dataPointIndex])
      : NaN;

  const point =
    w &&
    w.config &&
    w.config.series &&
    w.config.series[index] &&
    w.config.series[index].data &&
    dataPointIndex >= 0
      ? w.config.series[index].data[dataPointIndex]
      : null;

  const colour =
    point && point.fillColor
      ? point.fillColor
      : '#9e9e9e';

  const display =
    Number.isFinite(value)
      ? value.toFixed(1) + ' ct/kWh'
      : '—';

  return (
    '<div style="display:flex;align-items:center;gap:7px;padding:7px 9px;font-size:10px;width:max-content;box-sizing:border-box;background:color-mix(in srgb,var(--ha-card-background,var(--card-background-color)) 35%,transparent);backdrop-filter:blur(1px);-webkit-backdrop-filter:blur(1px);border-radius:6px;border:1px solid var(--divider-color);color:var(--primary-text-color);font-family:inherit;box-shadow:none;font-weight:700;">' +
