const startOfTomorrow = new Date();
startOfTomorrow.setHours(24, 0, 0, 0);

const tomorrowTimestamp =
  startOfTomorrow.getTime();

const withOpacity = (hex, opacity) => {
  const value = hex.replace('#', '');

  const red =
    parseInt(value.slice(0, 2), 16);

  const green =
    parseInt(value.slice(2, 4), 16);

  const blue =
    parseInt(value.slice(4, 6), 16);

  return `rgba(${red}, ${green}, ${blue}, ${opacity})`;
};

return marks.map(interval => {
  const timestamp =
    new Date(interval.start).getTime();

  const colour =
    interval.is_now
      ? '#009ac7'
      : (colours[interval.mark] || '#9e9e9e');

  return {
    x: timestamp,
    y: Number(interval.price),
    fillColor:
      timestamp >= tomorrowTimestamp &&
      !interval.is_now
        ? withOpacity(colour, 0.55)
        : colour
  };
});

